#!/usr/bin/env python3
"""Machine check of C02 OUT1/OUT2 surface: kind routing, frontmatter/path parity,
architecture subtype composition, specification api-contract sections, and
zero direct feature registrations."""
from __future__ import annotations

import json
import re
import sys
from pathlib import Path

REPO = Path(sys.argv[1]).resolve(strict=True)
GRAPH = REPO / ".dev-graph" / "state" / "graph.json"
CONTRACT = json.loads((REPO / ".dev-graph" / "templates" / "template-contract.json").read_text(encoding="utf-8"))
ARTIFACTS = CONTRACT["artifacts"]
ROOT_MAP = CONTRACT["graph_projection"]["root_map"]
PLACEHOLDERS = CONTRACT["placeholder_tokens"]

API_CONTRACT_SECTIONS = [
    "識別と目的", "認証・認可", "Request", "Response", "Validation・ビジネスルール",
    "Error contract", "実行セマンティクス", "キャッシュ・ページング", "可観測性と監査",
    "セキュリティ確認", "Contract tests",
]
SUBTYPE_SECTIONS = {
    "backend": ("Backend architecture", [
        "Runtime and architecture pattern", "Domain and module boundaries",
        "API and service contracts", "Data and transaction behavior",
        "Async processing", "Security and resilience", "Operations and verification",
    ]),
    "security": ("Security architecture", [
        "Assets, actors and threat model", "Identity and authorization",
        "Data and secret protection", "Application and supply-chain controls",
        "Detection and response", "Security verification",
    ]),
}

graph = json.loads(GRAPH.read_text(encoding="utf-8"))
nodes = graph["nodes"]
failures: list[str] = []
report: dict = {"graph_revision": graph.get("graph_revision"), "node_count": len(nodes), "nodes": []}


def headings(text: str) -> list[tuple[int, str]]:
    out = []
    for line in text.splitlines():
        match = re.match(r"^(#{1,6})\s+(.*?)\s*$", line)
        if match:
            out.append((len(match.group(1)), match.group(2)))
    return out


def split_frontmatter(text: str) -> tuple[str, str]:
    lines = text.splitlines()
    assert lines[0].strip() == "---"
    end = next(i for i in range(1, len(lines)) if lines[i].strip() == "---")
    return "\n".join(lines[1:end]), "\n".join(lines[end + 1:])


for node in nodes:
    entry: dict = {"graph_node_id": node["graph_node_id"], "artifact_kind": node["artifact_kind"],
                   "file_path": node["file_path"], "artifact_subtypes": node["artifact_subtypes"]}
    kind = node["artifact_kind"]
    path = node["file_path"]
    node_id = node["graph_node_id"]

    if not path.startswith(ROOT_MAP[kind]):
        failures.append(f"{node_id}: path root mismatch {path} not under {ROOT_MAP[kind]}")
    artifact = REPO / path
    if not artifact.is_file():
        failures.append(f"{node_id}: artifact missing {path}")
        report["nodes"].append(entry)
        continue

    text = artifact.read_text(encoding="utf-8")
    front_raw, body = split_frontmatter(text)
    front_keys = {m.group(1) for m in re.finditer(r"(?m)^([A-Za-z_][A-Za-z0-9_-]*):", front_raw)}
    missing_front = sorted(set(CONTRACT["common_frontmatter"]["required"]) - front_keys)
    if missing_front:
        failures.append(f"{node_id}: frontmatter missing {missing_front}")
    for key in ("graph_node_id", "artifact_kind", "file_path", "template_id", "template_version"):
        match = re.search(rf"(?m)^{key}:\s*(.*)$", front_raw)
        value = json.loads(match.group(1)) if match else None
        if value != node[key]:
            failures.append(f"{node_id}: frontmatter parity {key} {value!r} != {node[key]!r}")

    heads = headings(body)
    head_texts = {text for _, text in heads}
    required = list(ARTIFACTS[kind]["required_sections"])
    missing = [section for section in required if section not in head_texts]
    if missing:
        failures.append(f"{node_id}: missing required sections {missing}")
    entry["required_sections_present"] = len(required) - len(missing)
    entry["required_sections_total"] = len(required)

    top_level = [text for level, text in heads if level <= 2]
    for token in PLACEHOLDERS:
        if token in body:
            failures.append(f"{node_id}: placeholder token {token!r} present in body")

    if kind == "architecture":
        subtypes = node["artifact_subtypes"]
        if not subtypes:
            failures.append(f"{node_id}: architecture requires at least one subtype")
        composed = {}
        for subtype, (title, sections) in SUBTYPE_SECTIONS.items():
            if subtype in subtypes:
                block_missing = [s for s in sections if s not in head_texts]
                if title not in head_texts:
                    block_missing.append(title)
                if block_missing:
                    failures.append(f"{node_id}: subtype {subtype} missing {block_missing}")
                composed[subtype] = len(sections) - len([s for s in block_missing if s in sections])
        for subtype in subtypes:
            if subtype not in SUBTYPE_SECTIONS:
                failures.append(f"{node_id}: unexpected subtype {subtype}")
        # non-selected subtypes must be explicitly marked N/A in the subtype section
        for subtype in ("Frontend", "Infrastructure", "Data"):
            if not re.search(rf"(?m)^- {subtype}: N/A: .+$", body):
                failures.append(f"{node_id}: subtype {subtype} lacks explicit N/A reason")
        entry["subtype_sections_composed"] = composed

    if kind == "specification":
        api_blocks = [text for level, text in heads if level == 3 and text.startswith("API: ")]
        entry["api_endpoint_blocks"] = api_blocks
        if not api_blocks:
            failures.append(f"{node_id}: api_changed specification has no API contract block")
        for level, text in heads:
            pass
        # every api-contract required section must appear under each endpoint block
        positions = [i for i, (level, text) in enumerate(heads) if level == 3 and text.startswith("API: ")]
        for index, start in enumerate(positions):
            end = positions[index + 1] if index + 1 < len(positions) else len(heads)
            block = {text for level, text in heads[start:end] if level >= 4}
            block_missing = [s for s in API_CONTRACT_SECTIONS if s not in block]
            if block_missing:
                failures.append(f"{node_id}: endpoint {heads[start][1]} missing api-contract sections {block_missing}")
        if "api" not in node["artifact_subtypes"]:
            failures.append(f"{node_id}: api-changed specification must record the api conditional template in artifact_subtypes")

    report["nodes"].append(entry)

# direct feature registration must be zero for a plain `add` batch
feature_nodes = [n["graph_node_id"] for n in nodes if n["artifact_kind"] == "feature"]
features_dir = REPO / ROOT_MAP["feature"]
feature_files = sorted(p.name for p in features_dir.glob("*.md")) if features_dir.is_dir() else []
report["feature_nodes"] = feature_nodes
report["feature_files"] = feature_files
if feature_nodes:
    failures.append(f"direct feature registration detected in graph: {feature_nodes}")
if feature_files:
    failures.append(f"direct feature artifact detected under features/: {feature_files}")

kinds = sorted(n["artifact_kind"] for n in nodes)
report["kinds"] = kinds
if kinds != ["architecture", "document", "issue", "specification", "task"]:
    failures.append(f"unexpected kind set: {kinds}")

report["failures"] = failures
report["result"] = "PASS" if not failures else "FAIL"
print(json.dumps(report, ensure_ascii=False, indent=2))
sys.exit(0 if not failures else 1)

